  "wild woman|*": {"id":84708,"poster":"/oWOseenyLLFbfHEtt6dX68u3qap.jpg","title":"Captive Wild Woman","title_en":"Captive Wild Woman","overview_en":"An insane scientist doing experimentation in glandular research becomes obsessed with transforming a female gorilla into a human...even though it costs human life.","kind":"movie","genre_ids":[27,878],"vote_average":5.321,"vote_count":39,"imdb_id":"tt0035713","rt_critic":40,"rt_url":"https://www.rottentomatoes.com/m/captive_wild_woman/","imdb_rating":5.4,"imdb_votes":1075},
